-- area_product_reference : UPSERT B1-B9 (source de vérité CDC V3 / JSON)
ON CONFLICT (area_name, product_name) DO UPDATE SET
  product_family=EXCLUDED.product_family, association_level=EXCLUDED.association_level, area_group=EXCLUDED.area_group, legacy_area_name=EXCLUDED.legacy_area_name;

