CREATE TABLE IF NOT EXISTS buvette_stock_locations (
  id uuid primary key default gen_random_uuid(),
  area_name text not null, product_family text not null,
  depot_label text not null,
  depot_type text not null check (depot_type in ('buvette_locale','stockage_futs','auc_reserve','stock_est')),
  unique (area_name, product_family)
);
ON CONFLICT (area_name, product_family) DO UPDATE SET depot_label=EXCLUDED.depot_label, depot_type=EXCLUDED.depot_type;

-- Rattacher product_id par nom (insensible casse/espaces)
UPDATE area_product_reference apr SET product_id = p.product_id
FROM products p
WHERE apr.area_name ~ '^B[1-9]$' AND apr.product_id IS NULL
  AND lower(trim(p.product_name)) = lower(trim(apr.product_name)) AND p.active = true;

-- Lier explicitement « Cristalline 50cl » (CDC) au catalogue « Cristaline 50cl ».
UPDATE area_product_reference apr SET product_id = p.product_id
FROM products p
WHERE apr.area_name ~ '^B[1-9]$' AND apr.product_name = 'Cristalline 50cl'
  AND apr.product_id IS NULL AND p.product_name = 'Cristaline 50cl' AND p.active = true;

-- Créer au catalogue les produits buvette encore manquants (active=true, SANS prix).
SELECT DISTINCT apr.product_name,
  CASE apr.product_family
    WHEN 'Bière / Fûts' THEN 'Bières' WHEN 'Vins' THEN 'Vins' WHEN 'Gaz / Technique' THEN 'Matériel'
    WHEN 'Softs / Eau / Sirops' THEN CASE WHEN apr.product_name ILIKE 'Sirop%' THEN 'Sirops' ELSE 'Soft' END
    ELSE 'Soft' END,
  CASE apr.product_family WHEN 'Bière / Fûts' THEN 'fût' ELSE 'btl' END,
  true
FROM area_product_reference apr
WHERE apr.area_name ~ '^B[1-9]$' AND apr.product_id IS NULL
  AND NOT EXISTS (SELECT 1 FROM products p WHERE lower(trim(p.product_name)) = lower(trim(apr.product_name)));

UPDATE area_product_reference apr SET product_id = p.product_id
FROM products p
WHERE apr.area_name ~ '^B[1-9]$' AND apr.product_id IS NULL
  AND lower(trim(p.product_name)) = lower(trim(apr.product_name)) AND p.active = true;

-- ══ RPC fiche runner d'une buvette (lecture stricte référentiel + dépôt, SANS coût) ══
CREATE OR REPLACE FUNCTION get_buvette_runner(p_buvette_code text, p_event_id uuid, p_show_level text DEFAULT 'S')
RETURNS json LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_levels text[]; v_space_id uuid; v_libelle text; v_result json;
BEGIN
  v_levels := CASE upper(p_show_level)
    WHEN 'S' THEN ARRAY['S'] WHEN 'SR' THEN ARRAY['S','R']
    WHEN 'SRP' THEN ARRAY['S','R','P'] WHEN 'ALL' THEN ARRAY['S','R','P','C'] ELSE ARRAY['S'] END;
  SELECT space_id INTO v_space_id FROM spaces
    WHERE service_type='buvette' AND upper(trim(space_name))=upper(trim(p_buvette_code)) LIMIT 1;
  SELECT max(legacy_area_name) INTO v_libelle FROM area_product_reference WHERE area_name=upper(p_buvette_code);
  SELECT json_build_object(
    'buvette_code', upper(p_buvette_code), 'libelle', v_libelle,
    'event_id', p_event_id, 'show_level', upper(p_show_level),
    'lines', COALESCE(json_agg(l ORDER BY l.family_rank, l.association_level, l.product_name), '[]'::json)
  ) INTO v_result
  FROM (
    SELECT apr.product_family, apr.product_name, apr.association_level, apr.is_default,
      bsl.depot_label, bsl.depot_type,
      COALESCE(esl.initial_qty,0) AS stock_espace,
      COALESCE(sc.avg_consumption,0) AS moy_hist,
      COALESCE(sc.recommended_qty,0) AS reco,
      CASE apr.product_family WHEN 'Bière / Fûts' THEN 1 WHEN 'Vins' THEN 2 WHEN 'Champagne' THEN 3
        WHEN 'Softs / Eau / Sirops' THEN 4 WHEN 'Spiritueux / Apéritifs' THEN 5 WHEN 'Gaz / Technique' THEN 6 ELSE 7 END AS family_rank
    FROM area_product_reference apr
    LEFT JOIN buvette_stock_locations bsl ON bsl.area_name=apr.area_name AND bsl.product_family=apr.product_family
    LEFT JOIN event_stock_lines esl ON esl.event_id=p_event_id AND esl.product_id=apr.product_id AND esl.space_id=v_space_id
    LEFT JOIN space_product_coefficients sc ON sc.product_id=apr.product_id AND sc.space_id=v_space_id
    WHERE apr.area_name=upper(p_buvette_code) AND apr.association_level = ANY(v_levels)
      AND NOT (upper(p_buvette_code)<>'B8' AND apr.product_family IN ('Vins','Champagne','Spiritueux / Apéritifs'))
  ) l;
  RETURN v_result;
END $$;
GRANT EXECUTE ON FUNCTION get_buvette_runner(text,uuid,text) TO authenticated;

-- ══ RPC index des 9 buvettes (pour l'écran liste) ══
CREATE OR REPLACE FUNCTION get_buvette_runners_index(p_event_id uuid, p_show_level text DEFAULT 'S')
RETURNS json LANGUAGE sql SECURITY DEFINER AS $$
  SELECT COALESCE(json_agg(t ORDER BY t.area_name), '[]'::json) FROM (
    SELECT apr.area_name, max(apr.legacy_area_name) AS libelle,
      count(*) FILTER (WHERE apr.association_level = ANY(
        CASE upper(p_show_level) WHEN 'S' THEN ARRAY['S'] WHEN 'SR' THEN ARRAY['S','R']
          WHEN 'SRP' THEN ARRAY['S','R','P'] WHEN 'ALL' THEN ARRAY['S','R','P','C'] ELSE ARRAY['S'] END
      )) AS nb_a_monter,
      count(*) FILTER (WHERE apr.association_level='S') AS nb_socle,
      count(*) AS nb_total,
      array_agg(DISTINCT bsl.depot_type) FILTER (WHERE bsl.depot_type IS NOT NULL) AS depots
    FROM area_product_reference apr
    LEFT JOIN buvette_stock_locations bsl ON bsl.area_name=apr.area_name AND bsl.product_family=apr.product_family
    WHERE apr.area_name ~ '^B[1-9]$'
    GROUP BY apr.area_name
  ) t;
$$;
GRANT EXECUTE ON FUNCTION get_buvette_runners_index(uuid,text) TO authenticated;
